import { Routes } from '@angular/router';
import { Book } from './book/book';
import { BookAdd } from './book/book-add/book-add';
import { Chapter } from './chapter/chapter';
import { ChapterAdd } from './chapter/chapter-add/chapter-add';
import { Subjectz } from './subjectz/subjectz';
import { SubjectzAdd } from './subjectz/subjectz-add/subjectz-add';
import { RoutezFeatureModule } from '@_core/_route';

export const Routez: Routes = new RoutezFeatureModule(['Syllabus'], 'feature/syllabus')

  .feature(Subjectz, SubjectzAdd, 'subject', 'Subject')
  .feature(Book, BookAdd, 'book', 'Book')
  .feature(Chapter, ChapterAdd, 'chapter', 'Chapter')

.build();
